//! A ranking over time: bars overtake each other on springs as values count up.
use crate::primitives::{
    direct_touch::Contact,
    family::{Paint, PhaseClock, Slide, Tone, disabled_motion, face},
    glyph::{Glyph, icon},
    presentation::{column, hint, row, title, tr},
};
use gpui::{prelude::*, *};
use std::{cell::Cell, rc::Rc};

/// A named participant, identified across frames by its stable id.
#[derive(Clone, Debug)]
pub struct RaceEntry {
    pub id: SharedString,
    pub label: SharedString,
    /// Group id; bars take their hue from the group's series slot.
    pub group: Option<SharedString>,
    /// Interpolated display value, kept by the chart between frames.
    pub value: f32,
}
impl RaceEntry {
    pub fn new(id: impl Into<SharedString>, label: impl Into<SharedString>) -> Self {
        Self {
            id: id.into(),
            label: label.into(),
            group: None,
            value: 0.,
        }
    }
    /// Place the entry in a group that maps onto the series palette.
    pub fn with_group(mut self, group: impl Into<SharedString>) -> Self {
        self.group = Some(group.into());
        self
    }
}
/// Emitted when the inspected bar changes.
#[derive(Clone, Debug)]
pub struct RaceInspect {
    pub id: SharedString,
    pub value: f32,
    pub rank: usize,
}
/// One period of values keyed by the stable entry id. Missing ids count as zero.
#[derive(Clone, Debug)]
pub struct RaceFrame {
    pub period: SharedString,
    pub values: Vec<(SharedString, f32)>,
}
impl RaceFrame {
    pub fn new(period: impl Into<SharedString>, values: Vec<(SharedString, f32)>) -> Self {
        Self {
            period: period.into(),
            values,
        }
    }
    fn value(&self, id: &SharedString) -> f32 {
        self.values
            .iter()
            .find(|(key, _)| key == id)
            .map(|(_, value)| *value)
            .filter(|value| value.is_finite())
            .unwrap_or(0.)
            .max(0.)
    }
}
#[derive(Clone, Debug)]
pub struct RaceFrameChanged {
    pub index: usize,
}
#[derive(Clone, Debug)]
pub struct RacePlaybackChanged {
    pub playing: bool,
}
/// Series hues for the first four groups, matching the shared chart palette.
const SERIES: [u32; 4] = [0x55adff, 0x9c37be, 0xe66e00, 0x00a861];
const ROW_H: f32 = 36.;
const BAR_H: f32 = 24.;
const ROWS_TOP: f32 = 26.;
const LABEL_W: f32 = 104.;
const VALUE_GAP: f32 = 8.;
const TICK_LABEL_W: f32 = 48.;

/// Compact money in the reference's shape: `$14K`, `$660K`, `$3.87M`.
fn compact_value(value: f32, prefix: &str) -> String {
    let v = if value.is_finite() && value >= 0. {
        value
    } else {
        0.
    };
    let units = [(1e9, "B"), (1e6, "M")];
    for (scale, suffix) in units {
        if v >= scale {
            let text = format!("{:.2}", v / scale)
                .trim_end_matches('0')
                .trim_end_matches('.')
                .to_string();
            return format!("{prefix}{text}{suffix}");
        }
    }
    if v >= 1e3 {
        return format!("{prefix}{:.0}K", v / 1e3);
    }
    format!("{prefix}{v:.0}")
}
/// The smallest 1-2-5 multiple of a power of ten at least as large as `raw`.
fn nice_step(raw: f32) -> f32 {
    if !raw.is_finite() || raw <= 0. {
        return 1.;
    }
    let exponent = raw.log10().floor();
    let base = 10f32.powf(exponent);
    let scaled = raw / base;
    let multiple = if scaled <= 1. {
        1.
    } else if scaled <= 2. {
        2.
    } else if scaled <= 5. {
        5.
    } else {
        10.
    };
    multiple * base
}

struct MovingEntry {
    id: SharedString,
    rank: Slide,
    /// 0 while the row is outside the shown cut, 1 once it has risen in.
    shown: Slide,
    value: f32,
}
/// An interactive bar chart race with a playable, scrubbable timeline.
pub struct RaceBarChart {
    label: SharedString,
    meta: Option<SharedString>,
    data: Vec<RaceEntry>,
    groups: Vec<(SharedString, SharedString)>,
    moving: Vec<MovingEntry>,
    selected: Option<SharedString>,
    highlight: Option<SharedString>,
    initialized: bool,
    frames: Vec<RaceFrame>,
    position: f32,
    playing: bool,
    visible: bool,
    auto_started: bool,
    frame_duration: f32,
    looping: bool,
    bars: usize,
    prefix: SharedString,
    /// Playhead the bars follow. The reference springs this toward `position`.
    shown: Slide,
    /// Time already spent holding the last frame before playback stops.
    hold: f32,
    /// Crossfade between the outgoing and incoming period word.
    word: Slide,
    word_prev: SharedString,
    word_now: SharedString,
    word_index: usize,
    word_direction: f32,
    tick_step: f32,
    previous_tick_step: f32,
    tick_fade: Slide,
    clock: PhaseClock,
    last_age: f32,
    dragging: bool,
    track: Rc<Cell<Bounds<Pixels>>>,
    chart_bounds: Rc<Cell<Bounds<Pixels>>>,
    contact: Contact,
}
impl EventEmitter<RaceInspect> for RaceBarChart {}
impl EventEmitter<RaceFrameChanged> for RaceBarChart {}
impl EventEmitter<RacePlaybackChanged> for RaceBarChart {}
impl RaceBarChart {
    pub fn new(label: impl Into<SharedString>, data: Vec<RaceEntry>) -> Self {
        Self {
            label: label.into(),
            meta: None,
            data,
            groups: vec![],
            moving: vec![],
            selected: None,
            highlight: None,
            initialized: false,
            frames: Vec::new(),
            position: 0.,
            playing: false,
            visible: true,
            auto_started: false,
            frame_duration: 1.4,
            looping: false,
            bars: 8,
            prefix: SharedString::default(),
            shown: Slide::new(0.),
            hold: 0.,
            word: Slide::new(1.),
            word_prev: SharedString::default(),
            word_now: SharedString::default(),
            word_index: 0,
            word_direction: 1.,
            tick_step: 0.,
            previous_tick_step: 0.,
            tick_fade: Slide::new(1.),
            clock: PhaseClock::default(),
            last_age: 0.,
            dragging: false,
            track: Default::default(),
            chart_bounds: Default::default(),
            contact: Default::default(),
        }
    }
    /// Subtitle under the heading, such as "Year to date, 2025".
    pub fn with_meta(mut self, meta: impl Into<SharedString>) -> Self {
        self.meta = Some(meta.into());
        self
    }
    /// Named groups; the first four take the series hues and a legend appears.
    pub fn with_groups(mut self, groups: Vec<(SharedString, SharedString)>) -> Self {
        self.groups = groups;
        self
    }
    /// Value prefix such as "$" applied on bars, ticks, and the total.
    pub fn with_value_prefix(mut self, prefix: impl Into<SharedString>) -> Self {
        self.prefix = prefix.into();
        self
    }
    /// Bars shown at once; items below the cut slide out of view.
    pub fn with_bars(mut self, bars: usize) -> Self {
        self.bars = bars.clamp(1, 24);
        self
    }
    /// Item id whose name and value are emphasized.
    pub fn with_highlight(mut self, id: impl Into<SharedString>) -> Self {
        self.highlight = Some(id.into());
        self
    }
    /// Enable the timeline. Each period lasts 1400 ms by default.
    pub fn with_frames(mut self, frames: Vec<RaceFrame>) -> Self {
        self.frames = frames;
        self.position = 0.;
        self.update_values();
        self
    }
    pub fn with_frame_duration(mut self, seconds: f32) -> Self {
        if seconds.is_finite() && seconds > 0. {
            self.frame_duration = seconds.clamp(0.1, 60.);
        }
        self
    }
    pub fn with_autoplay(mut self, autoplay: bool) -> Self {
        self.auto_started = !autoplay;
        self
    }
    pub fn with_looping(mut self, looping: bool) -> Self {
        self.looping = looping;
        self
    }
    /// Replace frames without inventing values; position is clamped to the range.
    pub fn set_frames(&mut self, frames: Vec<RaceFrame>, cx: &mut Context<Self>) {
        self.frames = frames;
        self.position = self
            .position
            .min(self.frames.len().saturating_sub(1) as f32);
        if self.frames.len() < 2 && self.playing {
            self.set_playing(false, cx);
        }
        self.update_values();
        self.reconcile(cx);
        cx.notify();
    }
    /// Pause playback and paint scheduling while the host is hidden.
    pub fn set_visible(&mut self, visible: bool, cx: &mut Context<Self>) {
        if self.visible != visible {
            self.visible = visible;
            self.clock.restart(cx);
            self.last_age = 0.;
            cx.notify();
        }
    }
    pub fn set_playing(&mut self, playing: bool, cx: &mut Context<Self>) {
        self.auto_started = true;
        let playing = playing && self.frames.len() > 1 && !disabled_motion(cx);
        if self.playing != playing {
            self.playing = playing;
            self.clock.restart(cx);
            self.last_age = 0.;
            cx.emit(RacePlaybackChanged { playing });
            cx.notify();
        }
    }
    /// Glide the race to one period; playback pauses.
    pub fn set_frame(&mut self, index: usize, cx: &mut Context<Self>) {
        if self.frames.is_empty() {
            return;
        }
        self.set_playing(false, cx);
        let end = self.frames.len().saturating_sub(1);
        self.position = index.min(end) as f32;
        cx.emit(RaceFrameChanged {
            index: index.min(end),
        });
        cx.notify();
    }
    fn toggle_play(&mut self, cx: &mut Context<Self>) {
        if self.frames.len() < 2 {
            return;
        }
        let end = self.frames.len() - 1;
        if disabled_motion(cx) {
            let current = self.position.round() as usize;
            self.set_frame(if current >= end { 0 } else { current + 1 }, cx);
            return;
        }
        if !self.playing && self.position >= end as f32 {
            self.position = 0.;
            cx.emit(RaceFrameChanged { index: 0 });
        }
        self.set_playing(!self.playing, cx);
    }
    fn update_values_at(&mut self, at: f32) {
        if self.frames.is_empty() {
            return;
        }
        let index = (at.floor() as usize).min(self.frames.len() - 1);
        let next = (index + 1).min(self.frames.len() - 1);
        let t = f64::from((at - index as f32).clamp(0., 1.));
        for entry in &mut self.data {
            let a = f64::from(self.frames[index].value(&entry.id));
            let b = f64::from(self.frames[next].value(&entry.id));
            entry.value = (a + (b - a) * t).clamp(0., f64::from(f32::MAX)) as f32;
        }
    }
    fn update_values(&mut self) {
        self.update_values_at(self.position);
    }
    fn scrub(&mut self, x: Pixels, cx: &mut Context<Self>) {
        if self.frames.is_empty() {
            return;
        }
        self.set_playing(false, cx);
        let b = self.track.get();
        let fraction = ((x - b.origin.x) / b.size.width.max(px(1.))).clamp(0., 1.);
        let old = self.position.round() as usize;
        self.position = fraction * self.frames.len().saturating_sub(1) as f32;
        if disabled_motion(cx) {
            self.position = self.position.round();
        }
        let index = self.position.round() as usize;
        if old != index {
            cx.emit(RaceFrameChanged { index });
        }
        cx.notify();
    }
    fn release_scrub(&mut self, cx: &mut Context<Self>) {
        self.dragging = false;
        if self.frames.is_empty() {
            return;
        }
        let rounded = self.position.round();
        if (self.position - rounded).abs() > 0.001 {
            self.set_frame(rounded as usize, cx);
        } else {
            cx.notify();
        }
    }
    fn safe_value(entry: &RaceEntry) -> f32 {
        if entry.value.is_finite() {
            entry.value.max(0.)
        } else {
            0.
        }
    }
    fn order(&self) -> Vec<usize> {
        let mut order: Vec<_> = (0..self.data.len()).collect();
        order.sort_by(|&a, &b| {
            Self::safe_value(&self.data[b])
                .total_cmp(&Self::safe_value(&self.data[a]))
                .then(a.cmp(&b))
        });
        order
    }
    /// Reorder ranks and re-target the row springs from displayed positions.
    fn reconcile(&mut self, cx: &App) {
        let order = self.order();
        let cut = self.bars as f32;
        let mut old: Vec<Option<MovingEntry>> = std::mem::take(&mut self.moving)
            .into_iter()
            .map(Some)
            .collect();
        self.moving = self
            .data
            .iter()
            .enumerate()
            .map(|(i, item)| {
                let rank = order.iter().position(|&o| o == i).unwrap_or(0) as f32;
                let in_cut = rank < cut;
                let mut entry = old
                    .iter()
                    .position(|e| e.as_ref().is_some_and(|e| e.id == item.id))
                    .and_then(|i| old[i].take())
                    .unwrap_or_else(|| MovingEntry {
                        id: item.id.clone(),
                        rank: Slide::new(if in_cut { rank } else { cut }),
                        shown: Slide::new(if self.initialized { 0. } else { 1. }),
                        value: Self::safe_value(item),
                    });
                // Rank rides the source spring; overtakes read as one slide.
                entry.rank.duration(rank.min(cut), 0.5, cx);
                entry.shown.duration(if in_cut { 1. } else { 0. }, 0.26, cx);
                entry.value = Self::safe_value(item);
                entry
            })
            .collect();
        self.selected = self
            .selected
            .take()
            .filter(|id| self.data.iter().any(|v| v.id == *id));
        self.initialized = true;
    }
    fn select(&mut self, index: usize, cx: &mut Context<Self>) {
        let Some(item) = self.data.get(index) else {
            return;
        };
        if self.selected.as_ref() == Some(&item.id) {
            return;
        }
        let rank = self.order().iter().position(|v| *v == index).unwrap_or(0) + 1;
        self.selected = Some(item.id.clone());
        cx.emit(RaceInspect {
            id: item.id.clone(),
            value: Self::safe_value(item),
            rank,
        });
        cx.notify();
    }
    fn group_tone(&self, entry: &RaceEntry) -> Hsla {
        let index = entry
            .group
            .as_ref()
            .and_then(|g| self.groups.iter().position(|(id, _)| id == g));
        match index {
            Some(k) => rgb(SERIES[k % SERIES.len()]).into(),
            None => rgb(SERIES[0]).into(),
        }
    }
}
impl Render for RaceBarChart {
    fn render(&mut self, w: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        let p = Paint::get(cx);
        let bounds = self.chart_bounds.get();
        let viewport = w.viewport_size();
        let in_view = bounds.size.width > px(0.)
            && bounds.right() > px(0.)
            && bounds.left() < viewport.width
            && bounds.origin.y < viewport.height
            && bounds.origin.y + bounds.size.height > px(0.);
        let visible = self.visible && w.is_visible() && in_view;
        let reduced = disabled_motion(cx);
        let mut needs_frame = false;
        if reduced && self.playing {
            self.set_playing(false, cx);
        }
        if !self.auto_started && visible && self.frames.len() > 1 {
            self.auto_started = true;
            if !reduced {
                self.playing = true;
                self.clock.restart(cx);
                self.last_age = 0.;
                cx.emit(RacePlaybackChanged { playing: true });
            }
        }
        if self.playing && visible && !reduced && self.frames.len() > 1 {
            if !self.clock.age(cx).is_finite() {
                self.clock.restart(cx);
                self.last_age = 0.;
            }
            let age = self.clock.age(cx);
            // Wall-clock pacing: clamp only against tab-switch stalls so the
            // race never slows down on a throttled frame rate.
            let delta = (age - self.last_age).clamp(0., 0.25);
            self.last_age = age;
            let before = self.position.round() as usize;
            let end = self.frames.len() - 1;
            let end_at = end as f32;
            if self.position >= end_at - 1e-6 {
                self.position = end_at;
                self.hold += delta;
                if self.hold >= 0.9 * self.frame_duration {
                    self.hold = 0.;
                    if self.looping {
                        self.position = 0.;
                    } else {
                        self.playing = false;
                        cx.emit(RacePlaybackChanged { playing: false });
                    }
                }
            } else {
                self.hold = 0.;
                self.position = (self.position + delta / self.frame_duration).min(end_at);
            }
            let current = self.position.round() as usize;
            if current != before {
                cx.emit(RaceFrameChanged { index: current });
            }
            needs_frame |= self.playing;
        } else {
            self.clock.restart(cx);
            self.last_age = 0.;
        }
        // The drawn clock springs toward the requested time; steps glide and a
        // replay sweeps back through every period.
        let now = cx.background_executor().now();
        if reduced {
            self.shown.reset(self.position);
        } else {
            self.shown.duration(self.position, 0.42, cx);
        }
        let (shown, shown_moving) = self.shown.sample_batch(now, reduced);
        needs_frame |= shown_moving;
        if !self.frames.is_empty() {
            self.update_values_at(shown);
        }
        self.reconcile(cx);
        // Both words stay in the same reserved slot when the rounded period changes.
        let period_index = if self.frames.is_empty() {
            0
        } else {
            (shown.round() as usize).min(self.frames.len() - 1)
        };
        let period = self
            .frames
            .get(period_index)
            .map(|f| f.period.clone())
            .unwrap_or_default();
        if self.word_now != period {
            self.word_direction = if period_index < self.word_index {
                -1.
            } else {
                1.
            };
            self.word_index = period_index;
            self.word_prev = self.word_now.clone();
            self.word_now = period.clone();
            self.word
                .reset(f32::from(self.word_prev.is_empty() || reduced));
            self.word.duration(1., 0.16, cx);
        }
        let (word_t, word_moving) = self.word.sample_batch(now, reduced);
        needs_frame |= word_moving;
        let cut = self.bars.min(self.data.len().max(1));
        let mut rows: Vec<(f32, f32, f32)> = self
            .moving
            .iter_mut()
            .map(|v| {
                let (rank, rank_moving) = v.rank.sample_batch(now, reduced);
                let (shown, row_moving) = v.shown.sample_batch(now, reduced);
                needs_frame |= rank_moving || row_moving;
                (rank, shown, v.value)
            })
            .collect();
        let order = self.order();
        // Paint top-ranked rows last so overtake overlap matches the source.
        let paint_order: Vec<usize> = order.iter().rev().copied().collect();
        let axis_max = rows.iter().fold(1f32, |m, (_, _, v)| m.max(*v));
        let total: f32 = rows.iter().map(|(_, _, v)| *v).sum();
        let width = f32::from(bounds.size.width);
        let narrow = width > 0. && width < 400.;
        let bar_left = if narrow { 0. } else { LABEL_W + 12. };
        let tail_room = if narrow { 56. } else { 64. };
        let plot_w = (width - bar_left - tail_room).max(40.);
        // Nice steps choose labels only. Rounding the domain to a multiple of
        // the step caused every bar to jump whenever that multiple changed.
        let tick_count = (plot_w / (TICK_LABEL_W + 12.)).clamp(1., 5.);
        let tick_step = nice_step(axis_max / tick_count);
        if self.tick_step != tick_step {
            self.previous_tick_step = self.tick_step;
            self.tick_step = tick_step;
            self.tick_fade
                .reset(f32::from(self.previous_tick_step == 0. || reduced));
            self.tick_fade.duration(1., 0.16, cx);
        }
        let (tick_fade, ticks_moving) = self.tick_fade.sample_batch(now, reduced);
        if visible && (needs_frame || ticks_moving) {
            w.request_animation_frame();
        }
        let chart_bounds = self.chart_bounds.clone();
        let instructions = tr(
            cx,
            "Space plays or pauses, left and right arrows change the period, up and down arrows read the bars",
            "空格播放或暂停，左右方向键切换时间段，上下方向键读取条形",
        );
        let plot_label = format!(
            "{}, {}{}. {}",
            self.label,
            self.meta
                .clone()
                .map(|m| format!("{m}, "))
                .unwrap_or_default(),
            period,
            instructions
        );
        let prefix = self.prefix.to_string();
        let mut chart = div()
            .id("race-chart")
            .role(Role::Group)
            .tab_index(0)
            .relative()
            .w_full()
            .overflow_hidden()
            .h(px(ROWS_TOP + cut as f32 * ROW_H + 4.))
            .aria_label(plot_label)
            .on_hover(cx.listener(|s, over: &bool, w, cx| {
                // Keyboard focus suppresses pointer hover, so a keypress must
                // not clear the reading the reference keeps on screen.
                if !*over && !w.last_input_was_keyboard() {
                    s.selected = None;
                    cx.notify();
                }
            }))
            .on_key_down(cx.listener(|s, e: &KeyDownEvent, w, cx| {
                if !s.frames.is_empty() {
                    match e.keystroke.key.as_str() {
                        "left" => {
                            let i = (s.position.round() as usize).saturating_sub(1);
                            s.set_frame(i, cx);
                            w.prevent_default();
                            cx.stop_propagation();
                            return;
                        }
                        "right" => {
                            let i = (s.position.round() as usize + 1).min(s.frames.len() - 1);
                            s.set_frame(i, cx);
                            w.prevent_default();
                            cx.stop_propagation();
                            return;
                        }
                        "home" => {
                            s.set_frame(0, cx);
                            w.prevent_default();
                            cx.stop_propagation();
                            return;
                        }
                        "end" => {
                            s.set_frame(s.frames.len() - 1, cx);
                            w.prevent_default();
                            cx.stop_propagation();
                            return;
                        }
                        "space" | "enter" if !e.is_held => {
                            s.toggle_play(cx);
                            w.prevent_default();
                            cx.stop_propagation();
                            return;
                        }
                        _ => {}
                    }
                }
                let order = s.order();
                if order.is_empty() {
                    return;
                }
                let active = s
                    .selected
                    .as_ref()
                    .and_then(|id| order.iter().position(|&i| s.data[i].id == *id));
                let next = match e.keystroke.key.as_str() {
                    "down" => Some(match active {
                        None => 0,
                        Some(a) => (a + 1).min(order.len() - 1),
                    }),
                    "up" => Some(match active {
                        None => 0,
                        Some(a) => a.saturating_sub(1),
                    }),
                    "escape" => {
                        s.selected = None;
                        cx.notify();
                        w.prevent_default();
                        cx.stop_propagation();
                        return;
                    }
                    _ => return,
                };
                if let Some(rank) = next {
                    w.prevent_default();
                    cx.stop_propagation();
                    s.select(order[rank], cx);
                }
            }))
            .child(
                canvas(
                    move |b, w, _| {
                        let previous = chart_bounds.get();
                        let viewport = w.viewport_size();
                        let intersects = |bounds: Bounds<Pixels>| {
                            bounds.size.width > px(0.)
                                && bounds.origin.y < viewport.height
                                && bounds.origin.y + bounds.size.height > px(0.)
                        };
                        if previous.size != b.size || intersects(previous) != intersects(b) {
                            w.request_animation_frame();
                        }
                        chart_bounds.set(b);
                    },
                    |_, _, _, _| {},
                )
                .absolute()
                .inset_0(),
            )
            .child(
                div()
                    .absolute()
                    .left(px(bar_left))
                    .top(px(ROWS_TOP))
                    .w(px(1.))
                    .h(px(cut as f32 * ROW_H))
                    .bg(p.faint),
            );
        // Draw outgoing and incoming ticks against the same continuous scale.
        for (outgoing, step, opacity) in [
            (true, self.previous_tick_step, 1. - tick_fade),
            (false, self.tick_step, tick_fade),
        ] {
            if step <= 0. || (outgoing && opacity <= 0.) {
                continue;
            }
            for index in 1..=12 {
                let tick = step * index as f32;
                if tick >= axis_max {
                    break;
                }
                let alternate = if outgoing {
                    self.tick_step
                } else {
                    self.previous_tick_step
                };
                let ratio = tick / alternate;
                let shared = alternate > 0. && (ratio - ratio.round()).abs() < 0.01;
                if outgoing && shared {
                    continue;
                }
                if !shared && opacity <= 0. {
                    continue;
                }
                let x = bar_left + tick / axis_max * plot_w;
                if x < bar_left + plot_w - 2. {
                    let alpha = if shared { 1. } else { opacity };
                    let alpha = alpha * ((bar_left + plot_w - x) / 14.).clamp(0., 1.);
                    let nearest = (ratio.round() * alternate).clamp(0., axis_max);
                    let label_overlaps = outgoing
                        && nearest > 0.
                        && nearest < axis_max
                        && (tick - nearest).abs() / axis_max * plot_w < TICK_LABEL_W + 4.;
                    chart = chart
                        .child(
                            div()
                                .absolute()
                                .left(px(x))
                                .top(px(ROWS_TOP))
                                .w(px(1.))
                                .h(px(cut as f32 * ROW_H))
                                .bg(p.line.opacity(alpha)),
                        )
                        .when(!label_overlaps, |chart| {
                            chart.child(
                                div()
                                    .absolute()
                                    .left(px(x))
                                    .top(px(4.))
                                    .ml(px(-TICK_LABEL_W / 2.))
                                    .w(px(TICK_LABEL_W))
                                    .text_center()
                                    .text_size(px(12.))
                                    .line_height(px(12.))
                                    .text_color(p.faint.opacity(alpha))
                                    .child(compact_value(tick, &prefix)),
                            )
                        });
                }
            }
        }
        for i in paint_order {
            let item = &self.data[i];
            let (rank, row_shown, value) = rows[i];
            let is_selected = self.selected.as_ref() == Some(&item.id);
            let dim = self.selected.is_some() && !is_selected;
            let highlighted = self.highlight.as_ref() == Some(&item.id);
            let tone = self.group_tone(item);
            let fraction = (value / axis_max).clamp(0., 1.);
            let bar_px = (fraction * plot_w).max(2.);
            let wash = p
                .panel
                .blend(tone.opacity(if is_selected { 0.6 } else { 0.4 }));
            let value_x = bar_left + bar_px + VALUE_GAP;
            let label_inside = narrow;
            let place = order.iter().position(|&o| o == i).unwrap_or(0) + 1;
            chart = chart.child(
                div()
                    .id(("race-item", i))
                    .absolute()
                    .left_0()
                    .right_0()
                    .top(px(ROWS_TOP + rank * ROW_H))
                    .h(px(ROW_H))
                    .opacity(row_shown)
                    .on_hover(cx.listener(move |s, hover: &bool, _, cx| {
                        if *hover {
                            s.select(i, cx);
                        }
                    }))
                    .on_click(cx.listener(move |s, _, _, cx| s.select(i, cx)))
                    .when(!label_inside, |row| {
                        row.child(
                            div()
                                .absolute()
                                .top_0()
                                .left_0()
                                .w(px(LABEL_W))
                                .h(px(ROW_H))
                                .flex()
                                .items_center()
                                .justify_end()
                                .overflow_hidden()
                                .text_size(px(13.))
                                .line_height(px(ROW_H))
                                .text_color(if is_selected || highlighted {
                                    p.ink
                                } else {
                                    p.secondary
                                })
                                .font_weight(if highlighted {
                                    FontWeight::MEDIUM
                                } else {
                                    FontWeight::NORMAL
                                })
                                .child(item.label.clone()),
                        )
                    })
                    .child(
                        div()
                            .absolute()
                            .left(px(bar_left))
                            .top(px(6.))
                            .h(px(BAR_H))
                            .w(px(bar_px))
                            .overflow_hidden()
                            .rounded_tr(px(4.))
                            .rounded_br(px(4.))
                            .bg(wash)
                            .opacity(if dim { 0.55 } else { 1. })
                            .child(
                                div()
                                    .absolute()
                                    .right_0()
                                    .top_0()
                                    .bottom_0()
                                    .w(px(3.))
                                    .bg(tone),
                            )
                            .when(label_inside, |bar| {
                                bar.child(
                                    div()
                                        .absolute()
                                        .left(px(8.))
                                        .top_0()
                                        .bottom_0()
                                        .right(px(6.))
                                        .flex()
                                        .items_center()
                                        .overflow_hidden()
                                        .text_size(px(13.))
                                        .line_height(px(BAR_H))
                                        .text_color(p.ink)
                                        .child(item.label.clone()),
                                )
                            }),
                    )
                    .child(
                        div()
                            .absolute()
                            .top_0()
                            .left(px(if label_inside {
                                value_x.max(bar_left + 124.)
                            } else {
                                value_x
                            }))
                            .h(px(ROW_H))
                            .flex()
                            .items_center()
                            .text_size(px(13.))
                            .line_height(px(ROW_H))
                            .text_color(if highlighted {
                                p.ink
                            } else {
                                p.ink.opacity(0.9)
                            })
                            .font_weight(if highlighted {
                                FontWeight::MEDIUM
                            } else {
                                FontWeight::NORMAL
                            })
                            .child(compact_value(value, &prefix)),
                    )
                    .when(is_selected, |row| {
                        let tip_left = (bar_left + 14.).min((width - 252.).max(bar_left + 14.));
                        let tip_top =
                            (rank * ROW_H - 6.).clamp(2., (cut as f32 * ROW_H - 80.).max(2.));
                        row.child(
                            div()
                                .absolute()
                                .left(px(tip_left))
                                .top(px(tip_top))
                                .min_w(px(150.))
                                .max_w(px(240.))
                                .px(px(12.))
                                .py(px(10.))
                                .flex()
                                .flex_col()
                                .gap(px(2.))
                                .rounded(px(14.))
                                .border_1()
                                .border_color(p.line)
                                .bg(p.tray)
                                .shadow_lg()
                                .child(
                                    div()
                                        .text_size(px(12.))
                                        .line_height(px(18.))
                                        .text_color(p.secondary)
                                        .child(item.label.clone()),
                                )
                                .child(
                                    div()
                                        .text_size(px(16.))
                                        .line_height(px(20.8))
                                        .font_weight(FontWeight::MEDIUM)
                                        .text_color(p.ink)
                                        .child(compact_value(value, &prefix)),
                                )
                                .child(
                                    div()
                                        .text_size(px(12.))
                                        .line_height(px(18.))
                                        .text_color(p.faint)
                                        .child(format!(
                                            "{} {} / {}",
                                            tr(cx, "Rank", "排名"),
                                            place,
                                            self.data.len()
                                        )),
                                ),
                        )
                    }),
            );
        }
        rows.clear();
        // Legend appears once groups are named.
        let legend = (!self.groups.is_empty()).then(|| {
            row().flex_wrap().gap_x(px(16.)).gap_y(px(6.)).children(
                self.groups.iter().enumerate().map(|(k, (_, label))| {
                    let tone: Hsla = rgb(SERIES[k % SERIES.len()]).into();
                    row()
                        .id(("race-legend", k))
                        .items_center()
                        .gap(px(8.))
                        .text_size(px(12.))
                        .line_height(px(18.))
                        .text_color(p.secondary)
                        .child(
                            div()
                                .relative()
                                .size(px(10.))
                                .overflow_hidden()
                                .rounded_tr(px(3.))
                                .rounded_br(px(3.))
                                .bg(p.panel.blend(tone.opacity(0.4)))
                                .child(
                                    div()
                                        .absolute()
                                        .right_0()
                                        .top_0()
                                        .bottom_0()
                                        .w(px(2.))
                                        .bg(tone),
                                ),
                        )
                        .child(label.clone())
                }),
            )
        });
        // Head: the period rolls in large display type with the running total.
        let head = (!period.is_empty()).then(|| {
            row()
                .h(px(42.))
                .items_center()
                .justify_between()
                .gap(px(12.))
                .child(
                    div()
                        .relative()
                        .flex_1()
                        .min_w_0()
                        .h_full()
                        .overflow_hidden()
                        .text_size(px(if width > 0. && width < 480. { 24. } else { 30. }))
                        .line_height(px(36.))
                        .font_weight(FontWeight::MEDIUM)
                        .text_color(p.ink)
                        .child(
                            div()
                                .absolute()
                                .left_0()
                                .right_0()
                                .top(px(3. - self.word_direction * word_t * 5.))
                                .truncate()
                                .opacity(1. - word_t)
                                .child(self.word_prev.clone()),
                        )
                        .child(
                            div()
                                .absolute()
                                .left_0()
                                .right_0()
                                .top(px(3. + self.word_direction * (1. - word_t) * 5.))
                                .truncate()
                                .opacity(word_t)
                                .child(self.word_now.clone()),
                        ),
                )
                .child(
                    div()
                        .flex_none()
                        .text_right()
                        .text_size(px(13.))
                        .line_height(px(18.))
                        .text_color(p.faint)
                        .child(format!(
                            "{} {}",
                            tr(cx, "Total", "总计"),
                            compact_value(total, &prefix)
                        )),
                )
        });
        // Controls: round play button beside the scrubbing timeline.
        let controls = (!self.frames.is_empty()).then(|| {
            let end = self.frames.len() - 1;
            let index = (self.position.round() as usize).min(end);
            let first = self.frames[0].period.clone();
            let last = self.frames[end].period.clone();
            let fraction = if end > 0 {
                (self.position / end as f32).clamp(0., 1.)
            } else {
                0.
            };
            let track_bounds = self.track.clone();
            let touch = self.contact.listen(cx, |s, e: &TouchDragEvent, _, cx| {
                if matches!(e.phase, TouchPhase::Started | TouchPhase::Moved) {
                    s.scrub(e.position.x, cx);
                }
            });
            let track = div()
                .id("race-timeline")
                .role(Role::Slider)
                .tab_index(0)
                .aria_label(format!("{}, {}", self.label, tr(cx, "period", "时间段")))
                .aria_value(period.clone())
                .relative()
                .w_full()
                .h(px(36.))
                .cursor_pointer()
                .on_mouse_down(
                    MouseButton::Left,
                    cx.listener(|s, e: &MouseDownEvent, _, cx| {
                        s.dragging = true;
                        s.scrub(e.position.x, cx);
                    }),
                )
                .on_mouse_move(cx.listener(|s, e: &MouseMoveEvent, _, cx| {
                    if s.dragging {
                        s.scrub(e.position.x, cx);
                    }
                }))
                .on_mouse_up(
                    MouseButton::Left,
                    cx.listener(|s, _, _, cx| s.release_scrub(cx)),
                )
                .on_mouse_up_out(
                    MouseButton::Left,
                    cx.listener(|s, _, _, cx| s.release_scrub(cx)),
                )
                .on_key_down(cx.listener(|s, e: &KeyDownEvent, w, cx| {
                    let current = s.position.round() as usize;
                    let last = s.frames.len().saturating_sub(1);
                    let target = match e.keystroke.key.as_str() {
                        "left" | "down" => Some(current.saturating_sub(1)),
                        "right" | "up" => Some((current + 1).min(last)),
                        "home" => Some(0),
                        "end" => Some(last),
                        "space" | "enter" if !e.is_held => {
                            s.toggle_play(cx);
                            w.prevent_default();
                            cx.stop_propagation();
                            return;
                        }
                        _ => None,
                    };
                    if let Some(target) = target {
                        s.set_frame(target, cx);
                        w.prevent_default();
                        cx.stop_propagation();
                    }
                }))
                .child(
                    canvas(move |b, _, _| track_bounds.set(b), |_, _, _, _| {})
                        .absolute()
                        .inset_0(),
                )
                .child(
                    div()
                        .absolute()
                        .left_0()
                        .right_0()
                        .top(px(16.))
                        .h(px(4.))
                        .rounded(px(2.))
                        .bg(p.hover)
                        .child(
                            div()
                                .h_full()
                                .w(relative(fraction))
                                .rounded(px(2.))
                                .bg(p.panel.blend(p.ink.opacity(0.55))),
                        ),
                )
                .children((0..self.frames.len()).map(|i| {
                    let at = if end > 0 { i as f32 / end as f32 } else { 0. };
                    div()
                        .absolute()
                        .left(relative(at))
                        .top(px(17.))
                        .ml(px(-1.))
                        .size(px(2.))
                        .rounded_full()
                        .bg(if (i as f32) <= self.position + 1e-3 {
                            p.panel.opacity(0.9)
                        } else {
                            p.faint.opacity(0.6)
                        })
                }))
                .child(
                    div()
                        .absolute()
                        .left(relative(fraction))
                        .top(px(10.))
                        .ml(px(-8.))
                        .size(px(16.))
                        .rounded_full()
                        .bg(p.tray)
                        .border_1()
                        .border_color(p.line)
                        .shadow_sm(),
                )
                .child(touch);
            let play_label = if self.playing {
                tr(cx, "Pause", "暂停")
            } else if index == end {
                tr(cx, "Replay", "重新播放")
            } else {
                tr(cx, "Play", "播放")
            };
            row()
                .items_start()
                .gap(px(12.))
                .child(
                    face("race-play", play_label, 36., 18., Tone::Surface, cx)
                        .flex_none()
                        .size(px(36.))
                        .min_w(px(36.))
                        .p_0()
                        .rounded_full()
                        .border_1()
                        .border_color(p.line)
                        .bg(p.panel)
                        .hover(|s| s.bg(p.tray))
                        .child(icon(
                            if self.playing {
                                Glyph::Pause
                            } else if index == end {
                                Glyph::Undo
                            } else {
                                Glyph::Play
                            },
                            16.,
                            p.ink,
                        ))
                        // Press-started toggle: while playback animates, a
                        // web press/release pair can straddle a rebuild, so
                        // the release never matches the press to form a click.
                        .on_mouse_down(
                            MouseButton::Left,
                            cx.listener(|s, _, _, cx| s.toggle_play(cx)),
                        )
                        .on_key_down(cx.listener(|s, e: &KeyDownEvent, w, cx| {
                            if matches!(e.keystroke.key.as_str(), "enter" | "space") && !e.is_held {
                                s.toggle_play(cx);
                                w.prevent_default();
                                cx.stop_propagation();
                            }
                        })),
                )
                .child(
                    column().flex_1().min_w_0().gap(px(2.)).child(track).child(
                        row()
                            .justify_between()
                            .child(hint(first, p))
                            .child(hint(last, p)),
                    ),
                )
        });
        // Screen-reader table: every item's value for every period.
        let readings = div()
            .id("race-readings")
            .absolute()
            .size(px(1.))
            .overflow_hidden()
            .role(Role::Table)
            .aria_label(self.label.clone())
            .child(div().id("race-live").role(Role::Row).aria_label(format!(
                        "{}, {}",
                        period,
                        order
                            .first()
                            .and_then(|&i| self.data.get(i))
                            .map(|item| format!("{} {}", item.label, tr(cx, "leads", "领先")))
                            .unwrap_or_default()
                    )))
            .children(self.data.iter().enumerate().map(|(i, item)| {
                let cells = self
                    .frames
                    .iter()
                    .map(|f| compact_value(f.value(&item.id), &prefix))
                    .collect::<Vec<_>>()
                    .join(", ");
                div()
                    .id(("race-reading", i))
                    .role(Role::Row)
                    .aria_label(format!("{}: {}", item.label, cells))
            }));
        column()
            .w(px(720.))
            .max_w_full()
            .gap(px(20.))
            .p(px(if width > 0. && width < 420. { 16. } else { 24. }))
            .rounded(crate::foundation::surface_radius(cx))
            .bg(p.panel)
            .border_1()
            .border_color(p.line)
            .text_color(p.ink)
            .child(
                column()
                    .gap(px(2.))
                    .child(title(self.label.clone(), p))
                    .when_some(self.meta.clone(), |heading, meta| {
                        heading.child(
                            div()
                                .text_size(px(13.))
                                .line_height(px(18.))
                                .text_color(p.faint)
                                .child(meta),
                        )
                    }),
            )
            .when_some(head, |card, head| card.child(head))
            .child(chart)
            .when_some(legend, |card, legend| card.child(legend))
            .when_some(controls, |card, controls| card.child(controls))
            .child(readings)
    }
}

#[cfg(test)]
mod tests {
    use super::{BAR_H, RaceBarChart, RaceEntry, RaceFrame, compact_value, nice_step};
    use gpui::{TestAppContext, px, rgb, size};
    #[test]
    fn play_button_click_toggles_playback() {
        let mut app = TestAppContext::single();
        app.update(crate::init);
        let (view, w) = app.add_window_view(|_, _| {
            RaceBarChart::new(
                "Race",
                vec![RaceEntry::new("a", "A"), RaceEntry::new("b", "B")],
            )
            .with_autoplay(false)
            .with_frames(vec![
                RaceFrame::new("one", vec![("a".into(), 10.), ("b".into(), 30.)]),
                RaceFrame::new("two", vec![("a".into(), 40.), ("b".into(), 20.)]),
            ])
        });
        w.run_until_parked();
        let target = w.debug_bounds("Play").unwrap().center();
        w.simulate_click(target, gpui::Modifiers::default());
        w.run_until_parked();
        assert!(
            w.update(|_, cx| view.read(cx).playing),
            "clicking the play face should start playback"
        );
        let playing = w.update(|_, cx| view.read(cx).playing);
        let target = w
            .debug_bounds(if playing { "Pause" } else { "Play" })
            .unwrap()
            .center();
        w.simulate_click(target, gpui::Modifiers::default());
        w.run_until_parked();
        assert!(
            !w.update(|_, cx| view.read(cx).playing),
            "clicking again should pause playback"
        );
    }
    #[test]
    fn timeline_interpolates_host_values_and_treats_missing_as_zero() {
        let entries = vec![RaceEntry::new("a", "A"), RaceEntry::new("b", "B")];
        let frames = vec![
            RaceFrame::new("one", vec![("a".into(), 10.), ("b".into(), f32::NAN)]),
            RaceFrame::new("two", vec![("a".into(), 30.)]),
        ];
        let mut chart = RaceBarChart::new("Race", entries).with_frames(frames);
        chart.position = 0.5;
        chart.update_values();
        assert_eq!(chart.data[0].value, 20.);
        assert_eq!(chart.data[1].value, 0.);
    }
    #[test]
    fn compact_values_match_the_reference_format() {
        assert_eq!(compact_value(14_000., "$"), "$14K");
        assert_eq!(compact_value(660_000., "$"), "$660K");
        assert_eq!(compact_value(3_872_000., "$"), "$3.87M");
        assert_eq!(compact_value(999., ""), "999");
    }
    #[test]
    fn axis_steps_read_as_1_2_5_times_powers_of_ten() {
        assert_eq!(nice_step(0.4), 0.5);
        assert_eq!(nice_step(3.2), 5.);
        assert_eq!(nice_step(7.5), 10.);
        assert_eq!(nice_step(220_000.), 500_000.);
    }
    #[test]
    fn crossing_a_tick_step_keeps_the_leader_at_the_same_painted_bounds() {
        let mut app = TestAppContext::single();
        app.update(|cx| {
            crate::init(cx);
            crate::Theme::global_mut(cx).reduced_motion = true;
        });
        let (view, w) = app.add_window_view(|_, _| {
            RaceBarChart::new("Race", vec![RaceEntry::new("a", "Leader")])
                .with_autoplay(false)
                .with_frames(vec![
                    RaceFrame::new("May", vec![("a".into(), 249_990.)]),
                    RaceFrame::new("September", vec![("a".into(), 250_010.)]),
                ])
        });
        w.simulate_resize(size(px(630.), px(600.)));
        w.run_until_parked();
        w.update(|win, cx| {
            win.simulate_next_frame(cx);
            win.refresh();
        });
        w.run_until_parked();
        let leader = |w: &mut gpui::VisualTestContext| {
            w.update(|w, _| {
                let scale = w.scale_factor();
                w.painted_quads()
                    .into_iter()
                    .filter(|quad| (quad.bounds.size.height.0 / scale - BAR_H).abs() < 0.5)
                    .max_by(|a, b| a.bounds.size.width.0.total_cmp(&b.bounds.size.width.0))
                    .expect("leader bar should be painted")
                    .bounds
            })
        };
        let before = leader(w);
        w.update(|_, cx| view.update(cx, |chart, cx| chart.set_frame(1, cx)));
        w.run_until_parked();
        assert_eq!(leader(w), before);
    }
    #[test]
    fn group_tones_follow_the_series_palette() {
        let entries = vec![
            RaceEntry::new("a", "A").with_group("furniture"),
            RaceEntry::new("b", "B").with_group("lighting"),
        ];
        let chart = RaceBarChart::new("Race", entries).with_groups(vec![
            ("furniture".into(), "Furniture".into()),
            ("lighting".into(), "Lighting".into()),
        ]);
        let tone = chart.group_tone(&chart.data[1]);
        let expected: gpui::Hsla = rgb(0x9c37be).into();
        assert_eq!(tone, expected);
    }
}

//! Focus and activation shared by installed action controls.
use crate::foundation::Theme;
use gpui::{
    App, Context, Div, ElementId, Role, SharedString, Stateful, Window, div, prelude::*, px,
};

pub fn surface(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &App,
) -> Stateful<Div> {
    let label = label.into();
    let c = &Theme::global(cx).tokens.colors;
    let outline = c.focus_outline;
    div()
        .id(id)
        .role(Role::Button)
        .debug_selector(|| label.to_string())
        .aria_label(label)
        .tab_index(0)
        .min_h(px(44.))
        .px_3()
        .flex()
        .items_center()
        .justify_center()
        .rounded(Theme::global(cx).tokens.radius.md)
        .border_1()
        .border_color(c.border)
        .bg(c.surface)
        .text_color(c.foreground)
        .cursor_pointer()
        .hover(|s| s.opacity(0.8))
        .focus_visible(move |s| {
            s.shadow(vec![gpui::BoxShadow {
                color: outline,
                offset: gpui::point(px(0.), px(0.)),
                blur_radius: px(0.),
                spread_radius: px(2.),
                inset: false,
            }])
        })
}

pub fn activate<T: 'static>(
    el: Stateful<Div>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    // GPUI turns a completed Enter/Space press into one keyboard ClickEvent.
    // Registering a second key-down action also toggles on key-up in Web hosts.
    el.on_click(cx.listener(move |v, _, w, cx| f(v, w, cx)))
}

pub fn action<T: 'static>(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    let label = label.into();
    activate(surface(id, label.clone(), cx).child(label), cx, f)
}

/// Secondary action with a text label and a full keyboard/touch target.
pub fn quiet<T: 'static>(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    let c = Theme::global(cx).tokens.colors.clone();
    action(id, label, cx, f)
        .border_0()
        .bg(gpui::transparent_black())
        .text_size(px(12.))
        .text_color(c.text_secondary)
}

/// Monochrome control marks drawn with the same paths on both renderers.
#[derive(Clone, Copy)]
pub enum Mark {
    Hold,
    Check,
    Mic,
    Stop,
    Chevron,
    Up,
    Spark,
    Heart,
}
pub fn mark(kind: Mark, ink: gpui::Hsla) -> impl IntoElement {
    use gpui::{PathBuilder, canvas, point};
    canvas(
        |_, _, _| (),
        move |b, _, w, _| {
            let at = |x: f32, y: f32| point(b.origin.x + px(x), b.origin.y + px(y));
            let mut p = PathBuilder::stroke(px(1.55));
            match kind {
                Mark::Hold => {
                    p.move_to(at(3., 10.));
                    p.curve_to(at(8., 2.5), at(2.4, 2.7));
                    p.curve_to(at(13.3, 8.), at(13.2, 2.5));
                    p.move_to(at(4.6, 13.));
                    p.curve_to(at(5.5, 7.5), at(6., 10.5));
                    p.curve_to(at(10.5, 7.5), at(8., 3.5));
                    p.curve_to(at(9.4, 14.), at(11.1, 10.5));
                    p.move_to(at(8., 7.5));
                    p.curve_to(at(7.2, 12.1), at(8.6, 9.2));
                }
                Mark::Check => {
                    p.move_to(at(2.3, 8.1));
                    p.line_to(at(6.5, 12.));
                    p.line_to(at(13.8, 3.6));
                }
                Mark::Mic => {
                    p.move_to(at(5.4, 4.));
                    p.curve_to(at(10.6, 4.), at(8., -0.9));
                    p.line_to(at(10.6, 7.8));
                    p.curve_to(at(5.4, 7.8), at(8., 12.5));
                    p.line_to(at(5.4, 4.));
                    p.move_to(at(2.5, 7.5));
                    p.curve_to(at(13.5, 7.5), at(8., 16.5));
                    p.move_to(at(8., 12.));
                    p.line_to(at(8., 15.));
                    p.move_to(at(5.5, 15.));
                    p.line_to(at(10.5, 15.));
                }
                Mark::Stop => {
                    p = PathBuilder::fill();
                    p.move_to(at(3.5, 3.5));
                    p.line_to(at(12.5, 3.5));
                    p.line_to(at(12.5, 12.5));
                    p.line_to(at(3.5, 12.5));
                    p.close();
                }
                Mark::Up => {
                    p.move_to(at(8., 13.5));
                    p.line_to(at(8., 2.5));
                    p.move_to(at(3.2, 7.5));
                    p.line_to(at(8., 2.5));
                    p.line_to(at(12.8, 7.5));
                }
                Mark::Spark => {
                    p.move_to(at(8., 1.5));
                    p.curve_to(at(14.5, 8.), at(9.2, 6.7));
                    p.curve_to(at(8., 14.5), at(9.2, 9.3));
                    p.curve_to(at(1.5, 8.), at(6.8, 9.3));
                    p.curve_to(at(8., 1.5), at(6.8, 6.7));
                    p.close();
                }
                Mark::Heart => {
                    p.move_to(at(8., 13.8));
                    p.cubic_bezier_to(at(1.8, 5.6), at(5., 11.5), at(1.8, 8.6));
                    p.cubic_bezier_to(at(8., 4.4), at(1.8, 2.), at(5.8, 1.6));
                    p.cubic_bezier_to(at(14.2, 5.6), at(10.2, 1.6), at(14.2, 2.));
                    p.cubic_bezier_to(at(8., 13.8), at(14.2, 8.6), at(11., 11.5));
                    p.close();
                }
                Mark::Chevron => {
                    p.move_to(at(5., 6.5));
                    p.line_to(at(8., 9.5));
                    p.line_to(at(11., 6.5));
                }
            }
            if let Ok(path) = p.build() {
                w.paint_path(path, ink);
            }
        },
    )
    .size(px(16.))
    .flex_none()
}

/// Optional host language for labels owned by action controls; English is the default.
#[derive(Clone, Copy, Default, PartialEq, Eq)]
pub enum UiLanguage {
    #[default]
    English,
    Chinese,
}
impl gpui::Global for UiLanguage {}
impl UiLanguage {
    pub fn current(cx: &App) -> Self {
        cx.try_global::<Self>().copied().unwrap_or_default()
    }
    pub fn text<'a>(self, english: &'a str, chinese: &'a str) -> &'a str {
        match self {
            Self::English => english,
            Self::Chinese => chinese,
        }
    }
}

/// Optional host writing direction; left-to-right is the default. GPUI has no
/// direction property, so controls that place things on an inline axis read
/// this the way the Web reads `getComputedStyle(...).direction`.
#[derive(Clone, Copy, Default, PartialEq, Eq)]
pub enum UiDirection {
    #[default]
    Ltr,
    Rtl,
}
impl gpui::Global for UiDirection {}
impl UiDirection {
    pub fn current(cx: &App) -> Self {
        cx.try_global::<Self>().copied().unwrap_or_default()
    }
    pub fn is_rtl(self) -> bool {
        matches!(self, Self::Rtl)
    }
    /// Reverse the inline step when the reading direction runs the other way.
    pub fn inline_step(self, step: isize) -> isize {
        if self.is_rtl() { -step } else { step }
    }
}

//! Direct contact input for controls that cannot wait for a synthesized tap.
use gpui::{prelude::*, *};
use std::{cell::Cell, rc::Rc};
#[derive(Default, Clone)]
pub(crate) struct Contact(Rc<Cell<bool>>);
impl Contact {
    /// Mount over the gesture target. Only the topmost, hovered hitbox may claim a new contact.
    pub(crate) fn listen<T: 'static>(
        &self,
        cx: &Context<T>,
        handle: impl Fn(&mut T, &TouchDragEvent, &mut Window, &mut Context<T>) + 'static,
    ) -> impl IntoElement {
        let listener = cx.listener(handle);
        let active = self.0.clone();
        canvas(
            |bounds, w, _| w.insert_hitbox(bounds, HitboxBehavior::Normal),
            move |_, hit, w, _| {
                w.on_mouse_event(move |e: &TouchDragEvent, phase, w, cx| {
                    if phase.bubble() {
                        if e.phase == TouchPhase::Started {
                            active.set(hit.is_hovered(w));
                        }
                        if !active.get() {
                            return;
                        }
                        if matches!(e.phase, TouchPhase::Ended | TouchPhase::Cancelled) {
                            active.set(false)
                        }
                        if e.phase == TouchPhase::Started {
                            w.prevent_default();
                        }
                        listener(e, w, cx);
                        cx.stop_propagation();
                    }
                })
            },
        )
        .absolute()
        .inset_0()
    }
}

//! Compact action surfaces scoped to the button family.
use crate::foundation::{AccentPalette, Theme, ThemeMode};
use gpui::{prelude::*, *};
use web_time::Instant;
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum Tone {
    #[default]
    Surface,
    Primary,
    Muted,
    Danger,
    Success,
    Clear,
}
#[derive(Clone, Copy)]
pub struct Paint {
    pub stage: Hsla,
    pub panel: Hsla,
    pub tray: Hsla,
    pub hover: Hsla,
    pub ink: Hsla,
    pub secondary: Hsla,
    pub faint: Hsla,
    pub line: Hsla,
    pub bright: Hsla,
    pub(crate) focus: Hsla,
    pub inverse: Hsla,
    pub(crate) neutral_inverse: Hsla,
    accent: AccentPalette,
    pub danger: Hsla,
    pub success: Hsla,
}
impl Paint {
    pub fn get(cx: &App) -> Self {
        Self::for_theme(Theme::global(cx))
    }
    pub(crate) fn for_theme(theme: &Theme) -> Self {
        let mut paint = Self::for_mode(theme.mode);
        let tint = theme.accent.for_mode(theme.mode);
        if tint.is_transparent() {
            return paint;
        }
        paint.accent = theme.accent;
        paint.bright = paint.bright.blend(tint);
        paint.focus = theme.tokens.colors.focus_outline;
        paint.inverse = paint.accent.on_fill(paint.bright, paint.neutral_inverse);
        paint.hover = paint.hover.blend(tint.opacity(0.12));
        paint
    }
    pub(crate) fn primary_hover(self, strength: f32) -> Hsla {
        self.bright.blend(
            self.accent
                .hover_tint(self.bright, self.inverse, strength)
                .opacity(strength),
        )
    }
    pub fn for_mode(mode: ThemeMode) -> Self {
        let dark = mode == ThemeMode::Dark;
        let [
            stage,
            panel,
            tray,
            hover,
            ink,
            secondary,
            faint,
            line,
            bright,
            inverse,
            danger,
        ] = if dark {
            [
                0x242424, 0x191919, 0x303030, 0x353535, 0xf2f2f2, 0xb5b5b5, 0x898989, 0x2b2b2b,
                0xf2f2f2, 0x141414, 0xff746f,
            ]
        } else {
            [
                0xf5f5f5, 0xffffff, 0xffffff, 0xe9e9e9, 0x1a1a1a, 0x575757, 0x747474, 0xe2e2e2,
                0x181818, 0xfafafa, 0xbd302c,
            ]
        };
        Self {
            stage: rgb(stage).into(),
            panel: rgb(panel).into(),
            tray: rgb(tray).into(),
            hover: rgb(hover).into(),
            ink: rgb(ink).into(),
            secondary: rgb(secondary).into(),
            faint: rgb(faint).into(),
            line: rgb(line).into(),
            bright: rgb(bright).into(),
            focus: rgb(bright).into(),
            inverse: rgb(inverse).into(),
            neutral_inverse: rgb(inverse).into(),
            accent: AccentPalette::default(),
            danger: rgb(danger).into(),
            success: rgb(if dark { 0x53d986 } else { 0x008039 }).into(),
        }
    }
    pub fn colors(self, t: Tone) -> (Hsla, Hsla) {
        match t {
            Tone::Primary => (self.bright, self.inverse),
            Tone::Success => (self.panel.blend(self.success.opacity(0.10)), self.ink),
            Tone::Muted => (self.secondary, self.neutral_inverse),
            Tone::Clear => (transparent_black(), self.ink),
            _ => (self.panel, self.ink),
        }
    }
}
pub fn face(
    id: impl Into<ElementId>,
    name: impl Into<SharedString>,
    height: f32,
    r: f32,
    t: Tone,
    cx: &App,
) -> Stateful<Div> {
    let p = Paint::get(cx);
    let (bg, fg) = p.colors(t);
    let name = name.into();
    let ring = Theme::global(cx).tokens.colors.focus_outline;
    div()
        .id(id)
        .debug_selector({
            let name = name.clone();
            move || name.to_string()
        })
        .aria_label(name)
        .role(Role::Button)
        .tab_index(0)
        .h(px(height))
        .flex_none()
        .flex()
        .items_center()
        .justify_center()
        .gap(px(8.))
        .rounded(px(r))
        .bg(bg)
        .text_color(fg)
        .text_size(px(14.))
        .line_height(px(19.6))
        .font_weight(FontWeight::MEDIUM)
        .whitespace_nowrap()
        .cursor_pointer()
        .when(t == Tone::Danger, |e| {
            e.border_1().border_color(p.danger.opacity(0.42))
        })
        .when(t == Tone::Success, |e| {
            e.border_1().border_color(p.success.opacity(0.40))
        })
        .focus_visible(move |s| s.border_1().border_color(ring))
}
/// Analytic critically damped spring. Retargeting preserves instantaneous velocity.
#[derive(Clone, Copy, Debug)]
pub struct Slide {
    from: f32,
    to: f32,
    velocity: f32,
    start: Option<Instant>,
    omega: f32,
}
impl Slide {
    pub fn new(v: f32) -> Self {
        Self {
            from: v,
            to: v,
            velocity: 0.,
            start: None,
            omega: 12.47,
        }
    }
    pub fn snappy(v: f32) -> Self {
        Self {
            omega: 20.14,
            ..Self::new(v)
        }
    }
    /// Re-express the same trajectory in a shifted coordinate system, preserving velocity.
    pub fn translate(&mut self, delta: f32) {
        self.from += delta;
        self.to += delta;
    }
    pub fn reset(&mut self, v: f32) {
        self.from = v;
        self.to = v;
        self.velocity = 0.;
        self.start = None;
    }
    pub fn set(&mut self, v: f32, cx: &App) {
        self.retarget(v, self.omega, cx);
    }
    pub fn duration(&mut self, v: f32, visual_seconds: f32, cx: &App) {
        self.retarget(v, 5.236 / visual_seconds, cx)
    }
    /// Settle a directly manipulated value with the measured release speed (units per second).
    pub(crate) fn release(&mut self, target: f32, velocity: f32, seconds: f32, cx: &App) {
        if disabled_motion(cx) {
            self.reset(target);
            return;
        }
        let now = cx.background_executor().now();
        self.from = self.sample(now).0;
        self.to = target;
        self.velocity = velocity;
        self.omega = 5.236 / seconds;
        self.start = Some(now);
    }
    /// Stagger a first reveal without advancing the value before its slot starts.
    pub(crate) fn delayed(&mut self, target: f32, seconds: f32, delay: f32, cx: &App) {
        if self.to == target {
            return;
        }
        self.duration(target, seconds, cx);
        if let Some(start) = self.start.as_mut() {
            *start += std::time::Duration::from_secs_f32(delay.max(0.));
        }
    }
    fn retarget(&mut self, v: f32, omega: f32, cx: &App) {
        if disabled_motion(cx) {
            self.reset(v);
            return;
        }
        if self.to == v {
            return;
        }
        let now = cx.background_executor().now();
        let (pos, vel, _) = self.sample(now);
        self.from = pos;
        self.velocity = vel;
        self.omega = omega;
        self.to = v;
        self.start = Some(now);
    }
    pub(crate) fn sample(&self, now: Instant) -> (f32, f32, bool) {
        let Some(start) = self.start else {
            return (self.to, 0., false);
        };
        let t = now.saturating_duration_since(start).as_secs_f32();
        let d = self.from - self.to;
        let k = self.velocity + self.omega * d;
        let e = (-self.omega * t).exp();
        let offset = (d + k * t) * e;
        let vel = (self.velocity - self.omega * k * t) * e;
        if offset.abs() < 0.0008 && vel.abs() < 0.012 || t > 1.6 {
            (self.to, 0., false)
        } else {
            (self.to + offset, vel, true)
        }
    }
    /// Sample several springs at one instant and let the caller schedule a single frame.
    pub(crate) fn sample_batch(&self, now: Instant, reduced: bool) -> (f32, bool) {
        if reduced {
            (self.to, false)
        } else {
            let (value, _, active) = self.sample(now);
            (value, active)
        }
    }
    /// Sample from an input handler without scheduling a frame outside paint.
    pub fn value(&self, cx: &App) -> f32 {
        if disabled_motion(cx) {
            self.to
        } else {
            self.sample(cx.background_executor().now()).0
        }
    }
    pub fn get(&self, w: &Window, cx: &App) -> f32 {
        if disabled_motion(cx) {
            return self.to;
        }
        let (v, _, m) = self.sample(cx.background_executor().now());
        if m {
            w.request_animation_frame()
        }
        v
    }
}
pub fn disabled_motion(cx: &App) -> bool {
    cx.try_global::<Theme>().is_some_and(|t| t.reduced_motion)
}
/// A finite paint clock; never schedules frames once its last phase has finished.
#[derive(Clone, Copy, Default, Debug)]
pub struct PhaseClock(Option<Instant>);
impl PhaseClock {
    pub fn restart(&mut self, cx: &App) {
        self.0 = Some(cx.background_executor().now())
    }
    pub fn age(self, cx: &App) -> f32 {
        self.0.map_or(f32::INFINITY, |s| {
            cx.background_executor()
                .now()
                .saturating_duration_since(s)
                .as_secs_f32()
        })
    }
    pub fn time(self, end: f32, w: &Window, cx: &App) -> f32 {
        if disabled_motion(cx) {
            return end;
        }
        let t = self.age(cx);
        if t < end {
            w.request_animation_frame()
        }
        t.min(end)
    }
}
pub fn ease(t: f32) -> f32 {
    cubic_out(t, 0.16, 0.30)
}
/// Cubic-bezier(.22, 1, .36, 1) used by page-scale wipes.
pub fn standard_ease(x: f32) -> f32 {
    cubic_out(x, 0.22, 0.36)
}
fn cubic_out(x: f32, x1: f32, x2: f32) -> f32 {
    if x <= 0. || x >= 1. {
        return x.clamp(0., 1.);
    }
    let (mut lo, mut hi) = (0., 1.);
    for _ in 0..14 {
        let t = (lo + hi) * 0.5;
        let v = 1. - t;
        let at = 3. * x1 * v * v * t + 3. * x2 * v * t * t + t * t * t;
        if at < x { lo = t } else { hi = t }
    }
    1. - (1. - (lo + hi) * 0.5_f32).powi(3)
}
pub fn measure(text: &SharedString, size: f32, w: &Window) -> f32 {
    let mut style = w.text_style();
    style.font_weight = FontWeight::MEDIUM;
    let advance: f32 = w
        .text_system()
        .shape_line(text.clone(), px(size), &[style.to_run(text.len())], None)
        .width
        .into();
    (advance - 0.01 * size * text.chars().count() as f32).max(0.)
}
/// Pointer feedback lives in the element's stable hit box, independent of its paint.
pub fn press<T: 'static>(
    el: Stateful<Div>,
    cx: &Context<T>,
    field: fn(&mut T) -> &mut Slide,
) -> Stateful<Div> {
    el.on_mouse_down(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(1., cx);
            cx.notify()
        }),
    )
    .on_mouse_up(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(0., cx);
            cx.notify()
        }),
    )
    .on_mouse_up_out(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(0., cx);
            cx.notify()
        }),
    )
    .on_key_down(cx.listener(move |v, e: &KeyDownEvent, _, cx| {
        if matches!(e.keystroke.key.as_str(), "enter" | "space") {
            field(v).set(1., cx);
            cx.notify()
        }
    }))
    .on_key_up(cx.listener(move |v, e: &KeyUpEvent, _, cx| {
        if matches!(e.keystroke.key.as_str(), "enter" | "space") {
            field(v).set(0., cx);
            cx.notify()
        }
    }))
}

/// Stable glyph identities are matched in reading order, including common suffixes.
fn shared_glyphs(
    left: &[(SharedString, f32)],
    right: &[(SharedString, f32)],
) -> Vec<Option<usize>> {
    let stride = right.len() + 1;
    let mut lcs = vec![0u16; (left.len() + 1) * stride];
    for i in (0..left.len()).rev() {
        for j in (0..right.len()).rev() {
            lcs[i * stride + j] = if left[i].0 == right[j].0 {
                1 + lcs[(i + 1) * stride + j + 1]
            } else {
                lcs[(i + 1) * stride + j].max(lcs[i * stride + j + 1])
            };
        }
    }
    let mut out = vec![None; left.len()];
    let (mut i, mut j) = (0, 0);
    while i < left.len() && j < right.len() {
        if left[i].0 == right[j].0 {
            out[i] = Some(j);
            i += 1;
            j += 1
        } else if lcs[(i + 1) * stride + j] >= lcs[i * stride + j + 1] {
            i += 1
        } else {
            j += 1
        }
    }
    out
}
/// Paint two label phases in one measured slot; the outgoing face never affects layout.
pub fn lettering(
    old: SharedString,
    new: SharedString,
    time: f32,
    letters: bool,
    size: f32,
    ink: Hsla,
    width: f32,
) -> impl IntoElement {
    canvas(
        |_, _, _| (),
        move |b, _, w, cx| {
            let plain = old == new || time >= 0.48;
            let mut style = w.text_style();
            style.font_weight = FontWeight::MEDIUM;
            let width_of = |s: &SharedString| {
                f32::from(
                    w.text_system()
                        .shape_line(s.clone(), px(size), &[style.to_run(s.len())], None)
                        .width,
                )
            };
            let old_x = (width - width_of(&old)) * 0.5;
            let new_x = (width - width_of(&new)) * 0.5;
            if plain {
                let mut run = style.to_run(new.len());
                run.color = ink;
                let line = w
                    .text_system()
                    .shape_line(new.clone(), px(size), &[run], None);
                let _ = line.paint(
                    b.origin + point(px(new_x), px(0.)),
                    b.size.height,
                    TextAlign::Left,
                    None,
                    w,
                    cx,
                );
                return;
            }
            let pieces = |s: &SharedString| -> Vec<(SharedString, f32)> {
                let line =
                    w.text_system()
                        .shape_line(s.clone(), px(size), &[style.to_run(s.len())], None);
                s.char_indices()
                    .map(|(i, c)| (c.to_string().into(), line.x_for_index(i).into()))
                    .collect()
            };
            let mut runs = Vec::new();
            if letters && old.len() < 256 && new.len() < 256 {
                let left = pieces(&old);
                let right = pieces(&new);
                let pairs = shared_glyphs(&left, &right);
                let mut stable = vec![false; right.len()];
                let out = 1. - standard_ease(time / 0.16);
                let layout = 1. - (1. + 12.47 * time) * (-12.47 * time).exp();
                for ((glyph, dx), matched) in left.into_iter().zip(pairs) {
                    if let Some(j) = matched {
                        let x = old_x + dx;
                        stable[j] = true;
                        runs.push((glyph, x + (new_x + right[j].1 - x) * layout, 0., 1., 0.));
                    } else {
                        runs.push((glyph, old_x + dx, -3. * (1. - out), out, 2. * (1. - out)));
                    }
                }
                let mut order = 0;
                for ((glyph, dx), matched) in right.into_iter().zip(stable) {
                    if !matched {
                        let k = ease((time - (order as f32 * 0.016).min(0.1)) / 0.24);
                        runs.push((glyph, new_x + dx, 4. * (1. - k), k, 2. * (1. - k)));
                        order += 1;
                    }
                }
            } else {
                let incoming = ease(time / 0.16);
                runs.push((old.clone(), old_x, 0., 1. - standard_ease(time / 0.10), 0.));
                runs.push((new.clone(), new_x, 2. * (1. - incoming), incoming, 0.));
            }
            for (s, x, y, alpha, blur) in runs {
                if alpha < 0.001 || s.is_empty() {
                    continue;
                }
                let taps = if blur > 0.22 { 5 } else { 1 };
                let mut run = style.to_run(s.len());
                run.color = ink.opacity(alpha / if taps == 5 { 4.3 } else { 1. });
                let line = w.text_system().shape_line(s, px(size), &[run], None);
                for (dx, dy) in [(0., 0.), (-0.7, 0.), (0.7, 0.), (0., -0.7), (0., 0.7)]
                    .into_iter()
                    .take(taps)
                {
                    let _ = line.paint(
                        b.origin + point(px(x + dx * blur), px(y + dy * blur)),
                        b.size.height,
                        TextAlign::Left,
                        None,
                        w,
                        cx,
                    );
                }
            }
        },
    )
    .w(px(width.max(0.)))
    .h(px(size * 1.4))
    .flex_none()
}

#[cfg(test)]
mod spring_tests {
    use super::{Instant, Slide};
    use std::time::Duration;
    #[test]
    fn reversing_keeps_position_and_velocity() {
        let s = Instant::now();
        let mid = s + Duration::from_millis(75);
        let a = Slide {
            start: Some(s),
            to: 1.,
            ..Slide::new(0.)
        };
        let (x, v, _) = a.sample(mid);
        let reversed = Slide {
            start: Some(mid),
            from: x,
            velocity: v,
            to: 0.,
            ..a
        };
        assert_eq!(reversed.sample(mid), (x, v, true));
        assert_eq!(reversed.sample_batch(mid, false), (x, true));
        assert_eq!(reversed.sample_batch(mid, true), (0., false));
        assert!(reversed.sample(mid + Duration::from_millis(240)).0 < x);
        assert_eq!(
            reversed.sample(mid + Duration::from_secs(2)),
            (0., 0., false)
        );
    }
    #[test]
    fn unchanged_suffix_keeps_its_identity_across_label_swaps() {
        let glyphs = |s: &str| {
            s.chars()
                .map(|g| (gpui::SharedString::from(g.to_string()), 0.))
                .collect::<Vec<_>>()
        };
        let old = glyphs("Add to library");
        let new = glyphs("In library");
        let pairs = super::shared_glyphs(&old, &new);
        assert_eq!(
            &pairs[old.len() - 7..],
            &[
                Some(3),
                Some(4),
                Some(5),
                Some(6),
                Some(7),
                Some(8),
                Some(9)
            ]
        );
        assert_eq!(
            super::shared_glyphs(&glyphs("添加成员"), &glyphs("移除成员")),
            vec![None, None, Some(2), Some(3)]
        );
    }
}

#[cfg(test)]
mod accent_tests {
    use super::{AccentPalette, Paint, Theme, ThemeMode};
    use gpui::{Hsla, rgb};
    #[test]
    fn custom_accent_preserves_fill_and_picks_readable_ink_in_both_modes() {
        // Color pairs include near-threshold grays and hues with high/low relative
        // luminance despite identical HSL lightness (yellow and blue).
        for (hex, expected) in [
            (0xffffff, Hsla::black()),
            (0x000000, Hsla::white()),
            (0xffff00, Hsla::black()),
            (0x0000ff, Hsla::white()),
            (0x757575, Hsla::white()),
            (0x767676, Hsla::black()),
            (0xdfa4ef, Hsla::black()),
            (0x221144, Hsla::white()),
        ] {
            let fill: Hsla = rgb(hex).into();
            let accent = AccentPalette {
                light: fill,
                dark: fill,
            };
            let mut theme = Theme::default();
            theme.set_accent(accent);
            for mode in [ThemeMode::Light, ThemeMode::Dark] {
                theme.set_mode(mode);
                let colors = &theme.tokens.colors;
                let p = Paint::for_theme(&theme);
                assert_eq!(colors.accent, fill);
                assert_eq!(p.bright, fill);
                assert_eq!(colors.accent_foreground, expected, "#{hex:06x}");
                assert_eq!(p.inverse, expected);
                assert!(AccentPalette::contrast(p.inverse, p.bright) >= 4.5);
                assert!(AccentPalette::contrast(p.inverse, p.primary_hover(0.12)) >= 4.5);
                assert!(AccentPalette::contrast(colors.focus_outline, colors.surface_muted) >= 3.5);
                assert!(AccentPalette::contrast(colors.focus_outline, p.stage) >= 3.);
                // A tint applies to the primary fill, never to text on neutral/status surfaces.
                assert_eq!(p.neutral_inverse, Paint::for_mode(mode).inverse);
            }
        }
    }

    #[test]
    fn theme_presets_keep_their_authored_inks_and_focus_colors() {
        for (light, dark) in [
            (0x245bc4, 0x8bb4ff),
            (0x7142b6, 0xbc9cff),
            (0x08776d, 0x68d4c4),
            (0xb93c67, 0xff94b3),
            (0x955a08, 0xf4be69),
        ] {
            let mut theme = Theme::default();
            let pair = AccentPalette {
                light: rgb(light).into(),
                dark: rgb(dark).into(),
            };
            theme.set_accent(pair);
            for mode in [ThemeMode::Light, ThemeMode::Dark] {
                theme.set_mode(mode);
                let p = Paint::for_theme(&theme);
                let neutral = Paint::for_mode(mode);
                assert_eq!(p.bright, pair.for_mode(mode));
                assert_eq!(p.inverse, neutral.inverse);
                assert_eq!(theme.tokens.colors.focus_outline, pair.for_mode(mode));
            }
            theme.set_accent(AccentPalette::default());
            let p = Paint::for_theme(&theme);
            let neutral = Paint::for_mode(theme.mode);
            assert_eq!(p.bright, neutral.bright);
            assert_eq!(p.inverse, neutral.inverse);
        }
    }
}

